  4 | /* compare function for qsort */
  5 | int cmp(const void *a, const void *b)
  6 | {
  7 |     return *(const int *)a - *(const int *)b;
  8 | }
  9 | 
 10 | int main(void)
 11 | {
 12 |     int n;
 13 |     if (scanf("%d", &n) != 1) return 1;
 14 |     int *arr = malloc(sizeof(int) * (n + 1));
 15 |     for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
 16 |     qsort(arr, n, sizeof(int), cmp);
 17 |     for (int i = 0; i < n; i++) {
 18 |         if (i > 0) printf(" ");
 19 |         printf("%d", arr[i]);
 20 |     }
